import java.io.BufferedReader
import java.io.InputStreamReader
import java.math.BigInteger

const val MOD = 1000000007

fun main() {
    val reader = BufferedReader(InputStreamReader(System.in))
    val line = reader.readLine() ?: return
    val parts = line.split(" ")
    val n = parts[0].toInt()
    val k = parts[1].toInt()

    if (k >= n) {
        println(0)
        return
    }

    val maxN = n
    val fact = IntArray(maxN + 1)
    val invFact = IntArray(maxN + 1)

    fact[0] = 1
    for (i in 1..maxN) {
        fact[i] = (fact[i - 1].toLong() * i) % MOD
    }

    invFact[maxN] = modPow(fact[maxN], MOD - 2)
    for (i in maxN downTo 1) {
        invFact[i - 1] = (invFact[i].toLong() * i) % MOD
    }

    fun C(nn: Int, kk: Int): Int {
        if (kk < 0 || kk > nn) return 0
        return (fact[nn].toLong() * invFact[kk] % MOD * invFact[nn - kk]) % MOD
    }

    var ans = 0L
    for (m in 1..n - 1) {
        val x = (m - 1) / k
        if (x == 0) continue
        val term1 = fact[m - 1]
        val term2 = fact[n - m - 1]
        val sum = (C(n - 1, m) + x.toLong() * C(n, m + 1)) % MOD
        val add = term1.toLong() * term2 % MOD * sum % MOD
        ans = (ans + add) % MOD
    }

    println(ans)
}

fun modPow(a: Int, e: Int): Int {
    var base = a.toLong()
    var exp = e.toLong()
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) {
            res = (res * base) % MOD
        }
        base = (base * base) % MOD
        exp = exp shr 1
    }
    return res.toInt()
}
